    "outdoorTime" INTEGER,
    "meditation" BOOLEAN NOT NULL DEFAULT false,
    "meditationDuration" INTEGER,
    "journaling" BOOLEAN NOT NULL DEFAULT false,
    "readingTime" INTEGER,
