    "supplements" TEXT,
    "symptoms" TEXT,
    "deepworkMinutes" INTEGER DEFAULT 0,
    "tasksCompleted" INTEGER DEFAULT 0,
    "sleepHours" REAL,
    "recoveryAction" BOOLEAN NOT NULL DEFAULT false,
